if (iteration == 0) {
    return ""
} else {
    // for 8+2 naming convention, we might want to use %02d instead
    //return sprintf("%02d", iteration+1)
    return iteration + 1
}

import com.evolveum.midpoint.xml.ns._public.common.common_3.ActivationStatusType
import com.evolveum.midpoint.xml.ns._public.common.common_3.ShadowType

if (focus == null || focus.linkRef == null || focus.linkRef.isEmpty()) {
    return null
}

boolean isAnyAccountActive = focus.linkRef.any { link ->
    try {
        def shadow = midpoint.getObject(ShadowType.class, link.oid)
        if (shadow == null) return false

        // 1. Cas des comptes avec statut d'activation effectif (ex: AD)
        def effectiveStatus = shadow.activation?.effectiveStatus
        if (effectiveStatus == ActivationStatusType.ENABLED) {
            return true
        }

        // 2. Cas des comptes CSV / Ressources avec capacité simulée
        // Si administrativeStatus ou effectiveStatus est null, on vérifie si la projection est vivante (intent / lifecycle)
        def adminStatus = shadow.activation?.administrativeStatus
        if (adminStatus == ActivationStatusType.ENABLED) {
            return true
        }

        // 3. Si aucun statut d'activation n'est défini sur le Shadow (compte actif par défaut)
        if (effectiveStatus == null && adminStatus == null) {
            // Un compte sans statut d'activation explicite sur sa ressource est considéré comme actif
            return true
        }

        return false
    } catch (Exception e) {
        // En cas d'erreur de lecture du Shadow, on évite de désactiver par précaution
        return true
    }
}

// Ne désactiver le Focus que si TOUTES les projections sont explicitement à DISABLED
if (!isAnyAccountActive) {
    return ActivationStatusType.DISABLED
}

return ActivationStatusType.ENABLED
